parameters.jsCode:
const fs = require('fs');
const eventsPath = '/tmp/mosque_events.txt';

const summary = $input.first().json.candidates[0].content.parts[0].text;
const now = new Date();
const dateStr = now.toLocaleDateString('ar-SA', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const entry = `\n\n--- ${dateStr} ---\n${summary}`;

try {
  if (fs.existsSync(eventsPath)) {
    fs.appendFileSync(eventsPath, entry, 'utf8');
  } else {
    fs.writeFileSync(eventsPath, '=== أحداث وإعلانات المسجد ===\n' + entry, 'utf8');
  }
  return [{ json: { success: true, summary, message: 'تم حفظ الحدث بنجاح ✅' } }];
} catch (err) {
  return [{ json: { success: false, error: err.message } }];
}
